/** A component is its declaration, not the name it is exported under: `export default function Foo` followed by
 * `export { Foo }` or `export { Foo as Bar }` is one component, and a re-export belongs to the file that declares it, so
 * the exports of a module are taken once per declaration made in that module, under the export that carries the
 * declaration's own name, else the first. Everything that counts or compares components takes them from here. */
export function declaredExports(checker: any, moduleSymbol: any): any[] {
  const home = moduleSymbol.declarations?.[0]?.path
  const byDeclaration = new Map<string, any[]>()
  for (const exported of checker.getExportsOfModule(moduleSymbol)) {
    const symbol = exported.flags & SymbolFlags.Alias ? checker.getAliasedSymbol(exported) : exported
    const handle = symbol.declarations?.[0]
    if (handle?.path !== home) continue
    const key = `${handle.path}:${handle.resolve()?.pos}`
    byDeclaration.set(key, [...(byDeclaration.get(key) ?? []), exported])
  }
  return [...byDeclaration.values()].map((group) => {
    const own = group[0] && checker.getAliasedSymbol ? declaredName(group[0], checker) : undefined
    return group.find((e) => exportName(checker, e) === own) ?? group[0]
  })
}

function declaredName(exported: any, checker: any): string | undefined {
  const symbol = exported.flags & SymbolFlags.Alias ? checker.getAliasedSymbol(exported) : exported
  const name = symbol.declarations?.[0]?.resolve()?.name?.text
  return typeof name === 'string' && name !== '' ? name : undefined
}
